from collections.abc import Iterable, Iterator

from poker.learning.solver_dataset_batch import SolverDatasetBatch


class SolverDatasetTrainingPipeline:
	def __init__(self, batch_iterator, trainer):
		self.batch_iterator = batch_iterator
		self.trainer = trainer

	def run(self, records: Iterable) -> Iterator:
		for batch in self.batch_iterator.iterate(records):
			yield self.trainer.train_batch(batch)

from poker.learning.solver_dataset_training_pipeline import SolverDatasetTrainingPipeline


class FakeIterator:
	def iterate(self, records):
		yield from records


class FakeTrainer:
	def train_batch(self, batch):
		return batch


def test_solver_dataset_training_pipeline_forwards_batches():
	pipeline = SolverDatasetTrainingPipeline(FakeIterator(), FakeTrainer())

	result = list(pipeline.run([1, 2, 3]))

	assert result == [1, 2, 3]
